import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`sleep-schedule`,heroTitle:`Fix your child's sleep schedule in minutes`,heroSubtitle:`Perplexity Computer turns sleep patterns, nap timing, and bedtime struggles into a realistic age-based schedule.`,inputUrlCta:`Fix my schedule`,inputUrlPlaceholder:`Age, wake time, naps, bedtime, night wakings, current challenges`,inputUrlPrefill:`Use {url} as the sleep context for a customized child sleep plan. Build an age-appropriate daily sleep schedule based on current wake times, naps, bedtime, night wakings, early rising, and any sleep challenges. Explain the likely schedule misalignments, recommend a step-by-step transition plan, include a calming bedtime routine checklist, and add troubleshooting notes for common regressions or difficult nights.`,heroOverlaySteps:[`Reading the current sleep pattern, nap timing, and bedtime struggles`,`Comparing the routine with age-based sleep expectations and likely misalignments`,`Building a transition plan for better timing, routine, and consistency`,`Customized sleep schedule, bedtime checklist, and troubleshooting notes ready to use`],generatingSteps:[`Parsing {url} into sleep timing, challenges, and current schedule details`,`Designing an agent to identify the misalignments most likely driving the sleep issues`,`Configuring a step-by-step transition plan and bedtime routine checklist`,`Packaging the work into a practical schedule with troubleshooting guidance`],featureSectionTitle:`From sleep guesswork to a calmer routine`,featureCardTitles:[`Connects to your family planning workflow`,`Outputs you can use tonight`],featureCardDescriptions:[`Computer separates schedule analysis, bedtime planning, and troubleshooting so the final routine reflects the actual problem instead of generic sleep advice.`,`Shared notes and family planning tools can help caregivers follow the same routine and make changes consistently.`,`Daily sleep schedule. Transition steps. Bedtime routine. Regression notes. Computer gives your family something practical to follow.`],capabilitySectionTitle:`Your sleep schedule planner, on demand`,capabilitySectionSubtitle:`Describe the current routine, step away, and come back to a more workable schedule.`,capabilityCards:[{title:`Schedule Analysis`,description:`Computer can review wake times, naps, bedtime, and night wakings to highlight the timing issues most likely causing sleep friction.`},{title:`Age-Based Sleep Planning`,description:`Computer can turn age-appropriate sleep expectations into a daily plan that matches your current reality and goals.`},{title:`Transition Steps`,description:`Computer can break schedule changes into manageable steps so the family can shift the routine without changing everything at once.`},{title:`Bedtime Routine Checklist`,description:`Computer can create a simple bedtime sequence so each evening follows the same pattern and is easier to repeat.`},{title:`Remember the Challenges`,description:`Computer can remember the sleep issues and past routines you describe so follow-up updates keep the same context.`},{title:`Troubleshoot Regressions`,description:`Computer can help revisit the plan when naps change, night wakings return, or the schedule starts drifting again.`}]});export{t as default};
